  let db;
  try { db = JSON.parse(localStorage.getItem(STORAGE)); if(!db || db.version !== 1 || !Array.isArray(db.posts)) throw Error('Invalid'); }
  catch { db = makeSeed(); }
  const save = () => {try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch(e){console.warn('Storage unavailable',e);}};
  save();
  const ui = {view:'home',communityId:'c2',postId:null,anonId:null,sort:'hot',tab:'posts',modal:null,composerType:'post',profileMenu:false,replyTo:null,query:'',reportId:null,banUserId:null};
  const me = () => db.users.find(u=>u.id===db.currentUserId);
  const user = uid => db.users.find(u=>u.id===uid);
  const comm = cid => db.communities.find(c=>c.id===cid);
  const post = pid => db.posts.find(p=>p.id===pid);
  const membership = (uid,cid) => db.memberships.find(m=>m.userId===uid&&m.communityId===cid);
  const isMod = cid => membership(me().id,cid)?.role==='moderador';
  const banned = (uid,cid) => db.bans.some(b=>b.userId===uid&&b.communityId===cid&&(!b.until||new Date(b.until)>new Date()));
  const memberCount = cid => (comm(cid)?.baseMembers||0) + db.memberships.filter(m=>m.communityId===cid).length;
  const vote = (list, refField, objId) => db[list].find(v=>v.userId===me().id&&v[refField]===objId)?.value||0;
  const points = (item,list,refField,objectField) => (item?.baseScore||0)+db[list].filter(v=>v[refField]===item[objectField]).reduce((s,v)=>s+v.value,0);
  const postPoints = p => points(p,'postVotes','postId','id');
  const commentPoints = c => points(c,'commentVotes','commentId','id');
  const totalKarma = uid => (user(uid)?.karmaBase||0) + db.postVotes.filter(v=>post(v.postId)?.authorId===uid).reduce((s,v)=>s+v.value,0) + db.commentVotes.filter(v=>db.comments.find(c=>c.id===v.commentId)?.authorId===uid).reduce((s,v)=>s+v.value,0);
  const karmaParts = uid => ({posts:db.postVotes.filter(v=>post(v.postId)?.authorId===uid).reduce((s,v)=>s+v.value,0),comments:db.commentVotes.filter(v=>db.comments.find(c=>c.id===v.commentId)?.authorId===uid).reduce((s,v)=>s+v.value,0),base:user(uid)?.karmaBase||0});
  const canSee = p => !p.blindMode||p.authorId===me().id||db.comments.some(c=>c.postId===p.id&&c.authorId===me().id&&!c.deleted);
  const anonUnlocked = q => !q.blindMode || db.anonymousUnlocks.some(x=>x.questionId===q.id&&x.sessionToken===db.sessionToken);
  const numberOfReplies = pid => db.comments.filter(c=>c.postId===pid).length;
  const numberOfAnonAnswers = qid => db.anonymousAnswers.filter(a=>a.questionId===qid).length;
