  function setView(view, extra={}){Object.assign(ui, {view,profileMenu:false,replyTo:null,modal:null,...extra}); window.scrollTo({top:0,behavior:'instant'});render();}
  function navItem(view,label,iconName,extra=''){const active=ui.view===view||(view==='communities'&&ui.view==='community');return `<button class="nav-item ${active?'active':''}" data-action="navigate" data-view="${view}">${ico(iconName,19)}<span>${label}</span>${extra}</button>`;}

